fn shell_game(n: i32, x: i8) -> i8 {
    // Since the sequence of swaps (odd: swap 0↔1, even: swap 1↔2)
    // repeats with period 6 (because (swap1 ∘ swap0)^3 = identity in S₃),
    // we only need to look at n mod 6.
    let r = n.rem_euclid(6);
    match r {
        0 => x, // no net change
        1 => match x {
            0 => 1,
            1 => 0,
            2 => 2,
            _ => x,
        },
        2 => match x {
            0 => 2,
            1 => 0,
            2 => 1,
            _ => x,
        },
        3 => match x {
            0 => 2,
            1 => 1,
            2 => 0,
            _ => x,
        },
        4 => match x {
            0 => 1,
            1 => 2,
            2 => 0,
            _ => x,
        },
        5 => match x {
            0 => 0,
            1 => 2,
            2 => 1,
            _ => x,
        },
        _ => unreachable!(),
    }
}

